mapper.select:
SELECT id, title, description, detail_description, level, category, cover_url, teacher, teacher_intro, price, tags, course_outline, course_images, duration, student_count, rating, create_time FROM course
AND ( title LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%') OR tags LIKE CONCAT('%', #{keyword}, '%') OR teacher LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY create_time DESC LIMIT #{size} OFFSET #{offset}
